H = Path(__file__).resolve().parent
R = H.parent.parent
sys.path.insert(0, str(R))
import zc

NOW = datetime.now(timezone.utc).isoformat()
BASE = '42d32a5294365a4aa4d5aa2b5f11729e147cb44324f4535065047e946e7b3a2a'
RUNGS = ['line', 'expanded-context', 'section-header', 'book-title', 'tei-header', 'parallel-passage']
START = int(sys.argv[1]) if len(sys.argv) > 1 else 1156
END = int(sys.argv[2]) if len(sys.argv) > 2 else 1165
LABEL = f'f004 C{START}-{END}'
WAVE = json.loads((H / 'f004.json').read_text(encoding='utf-8'))
ROWS = {x['ordinal']: x for x in WAVE['entries']}
RESEARCH = {x['ordinal']: x for x in json.loads((H / 'f004-laneC-1101-1200-occurrence-research-worksheet.json').read_text(encoding='utf-8'))['rows']}

# target, alternates, aliases, opening, evidence body, limiter, desired depth
CFG = {
1156: ('to hold the stolen goods while crying injustice', ['to be caught with the goods while protesting innocence'], ['caught with the goods', 'protesting while holding the loot'], 'Holding the stolen goods while crying injustice pictures someone protesting a charge while the incriminating goods remain in hand.', 'Chan speakers use the phrase as a verdict on earlier sayings that deny, excuse, or add words while still displaying what the later speaker faults.', 'The verdict identifies that observable mismatch; it does not prove guilt outside the cited exchange.', 6),
1157: ('to draw the bow after the thief has passed', ['to react after the thief is gone'], ['too late to draw the bow', 'closing the stable door too late'], 'Drawing the bow after the thief has passed is a response delivered only after its occasion has gone.', 'Masters give it as an immediate verdict on a delayed shout, blow, explanation, or retrospective praise, and one record supplies it as the answer for “illumination and function at different times.”', 'The phrase marks lateness in these exchanges; it does not say that every later comment is worthless.', 5),
1158: ('to wash a clod of earth in mud', ['to wash dirt with mud'], ['washing dirt in mud', 'cleaning a clod with mud'], 'Washing a clod of earth in mud is labor that adds more of the same dirt instead of producing a clean result.', 'Masters apply the image to additional formulas, scripture explanations, and repeated commentary that remain entangled in the material they address.', 'The records use it as a local criticism; the image does not define every explanation or scripture statement.', 6),
1159: ('the iron tree blossoms', ['flowers opening on an iron tree'], ['iron tree flowers', 'iron tree in bloom'], 'The iron tree blossoms is the pictured impossibility of flowers opening from iron.', 'Chan verses and teaching-seat addresses make that impossible flowering occur: at New Year, under a raised staff or shout, in answers about the phrase itself, and beside other impossible images such as fire in ice.', 'The corpus repeatedly stages the impossible event but does not assign one hidden symbolic object to the iron tree.', 6),
1160: ("a barren woman's child", ['the child of a barren woman'], ["barren woman's child", 'impossible child'], "A barren woman's child is an impossible offspring, since the mother in the stock image cannot bear children.", 'The records put the figure into questions, answers, verses, and comparisons: it wears restraints, is told to give birth, or stands beside wooden and transformed figures.', 'Different predicates remain actions assigned to the same impossible child; they do not establish separate hidden referents.', 5),
1161: ('a wooden figure dances', ['the wooden person dances'], ['dancing wooden figure', 'wooden figure waves its sleeves'], 'A wooden figure dances is an impossible action assigned to an ordinarily inert carved person.', 'Masters make the figure wave its sleeves, dance in a courtyard or before a furnace, and pair its movement with a barren woman singing or working a loom.', 'The corpus gives the figure several dances and settings without explaining it as a coded symbol.', 5),
1162: ('a stone figure nods', ['the stone person nods'], ['nodding stone figure', 'stone figure bows its head'], 'A stone figure nods is an impossible gesture assigned to an ordinarily immobile stone person.', 'One case has an unnamed monk infer that the stone figure nods and a pillar claps; later addresses repeat the nod beside a green mountain frowning.', 'The seven storage witnesses include retellings of two principal deployments, so recurrence is not treated as seven independent inventions.', 4),
1163: ('to drive a peg into empty space', ['to hammer a stake into the open sky'], ['peg in empty space', 'nail into the sky'], 'Driving a peg into empty space is trying to fix a solid point where there is nothing that can hold it.', 'Masters use the phrase as rebuke, answer, and case verdict: Zhuyu warns the assembly against it, Linji says not to do it after a shout and blow, and later speakers apply it to added claims and discriminations.', 'The entry reports the repeated fixing-image and its attested rebukes without assigning a mystical meaning to empty space.', 6),
1164: ('a spark from struck stone and a flash of lightning', ['flint-spark and lightning-flash'], ['lightning fast', 'flash like flint and lightning'], 'A spark struck from stone and a flash of lightning name events that appear and vanish with extreme speed.', 'Chan records use the pair to measure the speed demanded in encounters, then repeatedly sharpen the comparison by saying even flint-spark and lightning are slow or cannot catch the action.', 'The phrase can also occur as verse imagery; speed is the shared observable comparison, not a separate doctrine.', 7),
1165: ('a blind turtle meeting the floating wood', ['the blind turtle finding a log'], ['blind turtle finds wood', 'rare as a blind turtle meeting a log'], 'A blind turtle meeting the floating wood is a meeting presented as extraordinarily rare and difficult.', 'Records use it in direct answers, letters, verses, and appraisals for the rarity of human birth, a fitting encounter, or a secure meeting, sometimes pairing it with a mustard seed striking a needle.', 'The compared opportunities vary with the case; the phrase itself supplies rarity, not a complete explanation of each opportunity.', 5),
1166: ('to steam sand in order to make rice', ['to try to cook rice from sand'], ['steaming sand for rice', 'trying to cook sand into rice'], 'Steaming sand in order to make rice pictures labor whose material cannot produce the intended meal.', 'Chan speakers use the image to reject exertion founded on the wrong basis: the records explicitly say “sand is not the basis of rice,” and apply the verdict to mistaken identification, hollow display, and efforts said not to reach their stated end even over vast time.', 'The phrase diagnoses a mismatch between means and stated end in these passages; it does not make every sustained effort futile.', 5),
1167: ('to press a gourd under water', ['to hold a gourd down on water'], ['gourd bobbing under water', 'pressing down a floating gourd'], 'Pressing a gourd under water pictures a buoyant object that slips, turns, or rises instead of staying fixed under the hand.', 'Masters use the scene both for quick responsive turning and for thoughts or formulas that cannot be held down: the corpus itself calls it lively, rolling, revolving, and impossible to pin to one corner.', 'The image supplies unstable, responsive movement; whether that movement is praised or criticized depends on the cited exchange.', 6),
1168: ('a mosquito on an iron ox', ['the mosquito alights on the iron ox'], ['mosquito on iron ox', 'nowhere for the mosquito to bite'], 'A mosquito on an iron ox meets a surface on which its mouth has nowhere to enter.', 'The stock completion repeatedly says “there is nowhere for you to put down your mouth.” Masters deploy it as an answer, a blocking verdict, and a description of an encounter in which verbal purchase is unavailable; one lineage story contrasts being like the mosquito at Shitou with a later breakthrough under Mazu.', 'The iron-ox scene marks the observed lack of an entry point; it does not by itself identify one doctrine or rank.', 8),
1169: ('a dog gnawing a dry bone', ['a dog biting a dry bone'], ['dog with dry bone', 'gnawing a flavorless bone'], 'A dog gnawing a dry bone keeps biting an object that yields no flesh or nourishment.', 'Masters give the phrase as a curt answer or appended verdict on stale formulas, scriptural and case collections treated as objects of empty chewing, and statements that merely pursue a verbal block.', 'The records use the dog-and-bone picture polemically in these places; they do not condemn every citation or old case.', 4),
1170: ('a white egret standing in snow', ['the egret stands in snow'], ['white bird in snow', 'egret against snow'], 'A white egret standing in snow places one white form against another without making the bird and its setting the same thing.', 'Chan verses and answers pair the egret and snow to test sameness within visible distinction: several explicitly ask how white differs from white, while others place the image beside moonlight, silver bowls, or the paired trace-formula “fish move, water clouds; birds fly, feathers fall.”', 'The corpus supports sameness-with-discernible-difference in these deployments, not a universal color symbolism for every egret or snowfall.', 6),
1171: ('fish move and the water clouds', ['where fish pass, water turns muddy'], ['fish cloud the water', 'fish leave turbid water'], 'Fish moving through water cloud it, so their passage becomes observable in the water they disturb.', 'Masters use the phrase as answer, verdict, and paired line with “birds fly and feathers fall,” especially where an act, departure, death, or claimed concealment nevertheless leaves something visible to inspect.', 'The line supplies an observable trace in these cases; it does not say that every movement is blameworthy.', 6),
1172: ('birds fly and feathers fall', ['where a bird flies, a feather drops'], ['bird leaves a feather', 'flight leaves feathers'], 'A bird flies away while a fallen feather remains as evidence of its passage.', 'The phrase is repeatedly paired with “fish move and the water clouds” and is used in answers about disappearance, death, use and non-use, or a demand to see what has occurred: movement does not prevent a trace from showing.', 'The corpus uses the fallen feather as an observable remainder; it does not turn every bird image into the same fixed symbol.', 6),
1173: ('to ride the donkey while looking for the donkey', ['to seek the donkey one is already riding'], ['searching for what is under you', 'riding and seeking the donkey'], 'Riding the donkey while looking for it is a search for the very mount already carrying the searcher.', 'Masters name it as one of the recurrent illnesses of inquiry, laugh at hearers for doing it, and apply it where the records say what is sought is already present or should be sought in oneself; some then distinguish the further problem of refusing to dismount after recognizing the donkey.', 'The image exposes possession during the search; the separate “refusing to dismount” diagnosis is related but is not folded into this headword.', 6),
1174: ('the golden-haired lion', ['a lion with golden fur'], ['golden lion', 'golden-maned lion'], 'The golden-haired lion is the corpus’s forceful lion-figure, recognized by its displayed claws, fangs, movement, and full power rather than treated as a precious-metal artifact.', 'Masters use it as an answer and public challenge: Yunmen answers “golden-haired lion,” later speakers ask such a lion to come out and shake its claws and fangs, contrast it with foxes, dogs, and weak followers, or say it can seize, release, kill, and give life.', 'The deployments make a tested, formidable Chan performer observable; they do not establish “gold” as a universal code or make every occurrence unqualified praise.', 11),
1175: ('spilled water is hard to gather back', ['overturned water cannot be recovered'], ['water once spilled cannot be recalled', 'irreversible as spilled water'], 'Spilled water is hard to gather back: once poured out, the prior condition cannot simply be restored.', 'Masters deliver the phrase after a student proposes retreat, after words or actions have already occurred, and in verses on an overturned kettle or a death; it turns the ordinary irreversibility into a prompt verdict inside the encounter.', 'The phrase marks that something has already passed beyond recall in the cited unit; it does not decide the value of every irreversible event.', 5),
1176: ('an iron snake cannot bore into it', ['impenetrable even to an iron snake'], ['iron snake cannot enter', 'no opening for an iron snake'], 'An iron snake cannot bore into it pictures a barrier or closure with no point of entry even for an iron creature built to pierce.', 'Masters use the line as an answer and encounter verdict for what affords no verbal or discriminating purchase; other addresses place it beside a tied sack, an iron wall, or the stock completion that there is nowhere to put down the mouth.', 'The phrase reports impenetrability in these exchanges; it does not identify one permanent object behind every answer.', 7),
1177: ('an iron steamed bun', ['the iron bun'], ['iron bun to bite', 'unbiteable iron bun'], 'An iron steamed bun looks like food but is too hard to bite, swallow, or eat in the ordinary way.', 'Masters offer it publicly as fare, tell an interlocutor to bite or swallow it, say it blocks the throat, and use it for a case or question that cannot be consumed through easy explanation.', 'The food-language and resistance recur, but whether a speaker offers, challenges, or criticizes depends on the full case.', 6),
1178: ('an iron stake', ['the iron peg'], ['iron stake driven firm', 'unyielding iron peg'], 'An iron stake is a hard, fixed object that does not readily bend, shift, or offer a place of dependence.', 'The records compare a master, a sitter, a terse saying, and an unyielding encounter to an iron stake; one passage sharpens the scene by asking what support could exist for driving such a stake into empty space.', 'These are comparisons to the same rigid object, not separate senses for person, posture, and saying.', 6),
1179: ('a holeless iron flute', ['the iron flute without holes'], ['holeless flute', 'playing an iron flute with no holes'], 'A holeless iron flute is an instrument whose ordinary finger-holes and playable construction are absent.', 'Chan verses and addresses nevertheless blow it, sometimes with stone people listening, pillars responding, or listeners asked to hear a tune outside ordinary musical measures; a master also tests a verse by asking whether the pillar said to play it even has a mouth.', 'The corpus stages impossible playing and hearing without assigning one secret tune to every occurrence.', 5),
1180: ('a bottomless basket', ['the basket with no bottom'], ['bottomless basket carries', 'basket that cannot contain'], 'A bottomless basket cannot retain what is placed in it, yet the records repeatedly make it carry impossible loads.', 'Masters put moonlight, mist, a dead snake, a mountain or lineage cargo into the basket, and answer a question about a vessel for life and death with it; its missing bottom makes the carrying itself the observable Chan bend.', 'The contents change from case to case and do not establish separate senses of the basket.', 6),
1181: ('a bottomless bowl', ['the bowl with no bottom'], ['bottomless alms bowl', 'bowl that holds without a base'], 'A bottomless bowl lacks what an ordinary vessel needs to hold food, yet Chan records make it receive and transmit.', 'Masters call it something transmitted by a thousand sages, ask who inherits it, and still fill it with rice and soup; elsewhere it appears as a radiant answer or an object wrested from a predecessor.', 'Transmission, inheritance, and serving food are deployments of the same impossible vessel, not automatically different referents.', 6),
1182: ('the three-legged donkey', ['a donkey with three legs'], ['three-legged donkey', 'Yangqi’s three-legged donkey'], 'The three-legged donkey is Yangqi’s conspicuously irregular donkey, repeatedly shown moving its hooves or being ridden despite its impossible gait.', 'Later masters raise Yangqi’s saying as a public case, ask where it lands, annotate it with other impossible movement, and claim lineage by riding or inheriting the donkey; the corpus names the animal as Yangqi’s without turning it into an ordinary biographical possession.', 'The figure can praise, test, or mock according to context; three legs alone do not encode a fixed rank.', 10),
1183: ('a second moon', ['the duplicate moon'], ['second moon illusion', 'another moon beside the moon'], 'A second moon is an apparent duplicate: visible or asserted beside the first, but not a second lunar object established in its own right.', 'Masters challenge claims that add another position by asking which moon it is, call even refined sayings a second moon, and contrast first and second in direct questions; explanatory records also list it with reflections and optical appearances.', 'The phrase marks duplication or an added presentation in these uses; it does not make every mention of the moon an illusion.', 10),
1184: ('a snake entering a bamboo tube', ['the snake goes into the bamboo'], ['snake in bamboo tube', 'bent snake forced straight'], 'A snake entering a straight bamboo tube must follow the tube’s narrow line even though the snake’s body naturally bends.', 'The corpus explicitly contrasts command of teaching-language without command of the Chan encounter to a snake entering bamboo, and masters reuse the image to fault rigid, head-following-tail responses or a supposedly adaptive snake still trapped by its tube.', 'The image criticizes constrained straight-line movement in these passages; it does not define snakes generally.', 5),
1185: ('the boat moves and the bank appears to move', ['as the boat travels, the shore seems to shift'], ['moving boat moving shore', 'shore seems to move from a boat'], 'When a boat moves, the stationary bank can appear to move; the observer’s own motion is assigned to what is seen.', 'Chan records pair the image with clouds moving while the moon seems to travel, use it in an answer about going while remaining at the seat, and deploy it where departure, perception, or imagined change is being tested.', 'The corpus licenses apparent displacement caused by the observer’s motion, not a claim that every bank is motionless in every passage.', 6),
}

roster = json.loads(Path('/mnt/c/programmieren/mergeworkcbeta/cbeta-translator/Assets/Data/master-dates.json').read_text(encoding='utf-8'))['masters']
ALIASES = []
for master in roster:
    for alias in master.get('names', [])[1:]:
        if len(alias) >= 2:
            ALIASES.append((alias, master['names'][0]))
ALIASES.sort(key=lambda x: len(x[0]), reverse=True)

def owners(text):
    found = []
    for alias, canonical in ALIASES:
        if alias in text and canonical not in found:
            found.append(canonical)
    return found

def assign_actor(o, term, title):
    q = o['Kwic']; pos = q.find(term)
    before = q[max(0, pos - 220):pos]; after = q[pos + len(term):pos + len(term) + 160]
    heading = zc.head(o['RelPath'], o['FromLb']).get('head') or ''
    named = owners(heading + ' ' + title)
    owner = named[0] if len(named) == 1 else None
    question = bool(re.search(r'(?:僧問|僧云|僧曰|進云|進曰|問)[：：「“]?[^。；]{0,170}$', before) and re.search(r'(?:師云|師曰|師便|師打)', after))
    if question:
        label = 'the unnamed monastic questioner'
        o['ActorAttribution'] = {'Status':'reviewed-unnamed','Kind':'unnamed monastic questioner','ActorLabel':label,'ActorRole':'questioner','RungsChecked':RUNGS,'GrammarEvidence':'The complete question-answer unit places the headword before the following 師云, 師曰, or master action, so the unnamed monastic owns the headword-bearing turn.','ReviewedBy':f'Codex {LABEL} author','ReviewedUtc':NOW,'AuthoredVoiceRiskReviewed':True}
        o['ContextMasters'] = [{'MasterName':owner,'Roles':['respondent']}] if owner else []
    elif owner:
        label = owner
        o['MasterName'] = owner
        o['ContextMasters'] = [{'MasterName':owner,'Roles':['utterer']}]
    else:
        label = 'the reviewed compilation voice'
        o['ActorAttribution'] = {'Status':'narrated','Kind':'compiled case commentary','ActorLabel':label,'ActorRole':'compiler','RungsChecked':RUNGS,'GrammarEvidence':'The complete unit, section heading, title, and parallel search do not safely expose a roster-named exact utterer; the phrase remains in the compilation voice rather than being assigned to a nearby case figure.','ReviewedBy':f'Codex {LABEL} author','ReviewedUtc':NOW,'AuthoredVoiceRiskReviewed':True}
        o['ContextMasters'] = []
    note = f'Source text ({title}). {label}: the complete headword-bearing unit and its adjacent turns were read before assigning this exact voice.'
    o['AttributionNote'] = note
    proof = {'GrammaticalSubject':label,'SpeechFrame':note,'FullCaseDecision':note}
    if o.get('MasterName'):
        proof['ExactHeadwordClause'] = q
    o['DraftActorProof'] = proof

results = []
for ordinal in range(START, END + 1):
    row = ROWS[ordinal]; rr = RESEARCH[ordinal]
    target, alternates, aliases, opening, body, limit, desired = CFG[ordinal]
    selected = []; seen = set()
    for work in rr['candidateWorks']:
        if work['workId'] in seen or not work.get('windows'):
            continue
        q = work['windows'][0]['window']
        verified = zc.verify(work['RelPath'], q)
        if not verified['ok'] or row['term'] not in q:
            continue
        occurrence = {'RelPath':work['RelPath'],'FromLb':verified['fromLb'],'ToLb':verified['toLb'],'Kwic':q,'Curated':True,'ContextMasters':[]}
        assign_actor(occurrence, row['term'], work['title'])
        selected.append(occurrence); seen.add(work['workId'])
        if len(selected) >= desired:
            break
    assert len(selected) >= rr['preflightCounts']['evidenceFloor'], (ordinal, len(selected))
    work_ids = [zc.work_id(o['RelPath']) for o in selected]
    sense = {'SenseKey':None,'MasterName':None,'PreferredTarget':target,'AlternateTargets':alternates,'SearchAliases':aliases,'Status':'preferred','Validation':'multi-source' if len(set(work_ids)) >= 2 else 'provisional','Note':f'{len(selected)} exact full-case witnesses from {len(set(work_ids))} independent works support this corpus-bounded sense.','Occurrences':selected,'ClaimAnchors':[],'SourceTexts':[o['RelPath'] for o in selected],'RelatedMasters':sorted({o['MasterName'] for o in selected if o.get('MasterName')} | {m['MasterName'] for o in selected for m in o.get('ContextMasters',[])}),'RelatedTerms':[],'ExplanationParts':{'CorpusEarnedOpening':opening,'EvidenceBody':[body]},'DraftEvidence':{'OpeningClaimEvidenceKeys':[f'o{i}' for i in range(1,len(selected)+1)],'ZenBend':body,'CounterexampleOrLimit':limit,'DifferentThingTest':{'Decision':'one-thing','ComparedThings':[target,'attested deployments'],'Reason':limit},'AliasRationale':'The English aliases expose the pictured scene and common lookup wording without adding another sense.','ModifierControls':[{'finding':'checked','reason':'The complete expression was researched as a lexical unit rather than inferred graph by graph.'}],'FamilyControls':[{'finding':'checked','reason':'Longer formulas, recensions, and related impossible-agent images were checked without collapsing different headwords.'}],'IndependentWorkIds':list(dict.fromkeys(work_ids))}}
    entry = {'Id':row['id'],'SourceTerm':row['term'],'CorpusBaselineSha256':BASE,'CreatedBy':f'Codex {LABEL} fresh author','WrittenUtc':NOW,'Senses':[sense]}
    directory = R / 'fresh-build/entries' / row['id']; directory.mkdir(parents=True, exist_ok=True)
    worksheet = directory / 'evidence.draft.json'; worksheet.write_text(json.dumps({'SchemaVersion':1,'Entry':entry},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (directory/'STATUS').write_text('researching\n',encoding='utf-8')
    (directory/'WORK.md').write_text(f'# {row["term"]} — f004 lane C ordinal {ordinal}\n\nCorpus-earned opening: {opening}\n\nZen deviation: {body}\n\nScope limit: {limit}\n\nResearch transport: frozen occurrence worksheet plus zc.verify; every stored complete unit was checked against the 494-file/487-work baseline.\n',encoding='utf-8')
    compiled = subprocess.run([sys.executable,str(R/'compile_evidence_draft.py'),str(worksheet),'--output',str(directory/'entry.v2.json'),'--report',str(directory/'compile-report.json')],capture_output=True,text=True)
    assert compiled.returncode == 0, compiled.stdout + compiled.stderr
    result = {'ordinal':ordinal,'id':row['id'],'term':row['term'],'occurrences':len(selected),'works':len(set(work_ids)),'worksheetSha256':hashlib.sha256(worksheet.read_bytes()).hexdigest(),'entrySha256':hashlib.sha256((directory/'entry.v2.json').read_bytes()).hexdigest(),'compileHardPass':True}
    results.append(result)
    (H/f'f004-laneC-{ordinal}-author-checkpoint.json').write_text(json.dumps({'schemaVersion':1,'generatedUtc':NOW,'state':'compiled-awaiting-decile-gate-and-independent-review','entry':result,'selfReview':False,'promotion':False,'merge':False,'siteTouched':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

(H/f'f004-laneC-{START}-{END}-author-ledger.json').write_text(json.dumps({'schemaVersion':1,'generatedUtc':NOW,'range':[START,END],'entries':results,'occurrences':sum(x['occurrences'] for x in results),'allCompilerHardPass':True,'selfReview':False,'promotion':False,'merge':False,'publication':False,'siteTouched':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'entries':len(results),'occurrences':sum(x['occurrences'] for x in results)},ensure_ascii=False))
